SInt8 prog_retrieve_option (Feature_Name feature_name)
{
	UInt8 i ;

	for (i = 0; i < FEATURE_NUM; i++)
	{
		if (feature_table[i].feature == feature_name)
			return feature_table[i].option_current ;
	}
	return -1 ;
}
